const entrada = $json.body ?? $json;

for (const campo of ['cliente', 'email_destino', 'mensagem']) {
  if (!entrada[campo] || typeof entrada[campo] !== 'string') {
    throw new Error(`Campo obrigatorio ausente: ${campo}`);
  }
}

return [{
  json: {
    cliente: entrada.cliente.trim(),
    email_destino: entrada.email_destino.trim(),
    mensagem: entrada.mensagem.trim(),
    recebido_em: new Date().toISOString()
  }
}];
